content.text:
{
  "primary_meaning": "the Word of God (as a living, piercing spiritual weapon of truth, conviction, and judgment)",
  "primary_basis": [
    "Ephesians 6:17 (sword of the Spirit, which is the word of God)",
    "Hebrews 4:12 (word of God sharper than any two-edged sword)",
    "Revelation 1:16; 2:12, 16; 19:15, 21 (sharp two-edged sword from Christ's mouth)"
  ],
  "alternatives": [
    {
      "meaning": "divine judgment, warfare, or destructive power (often executed by God or his agents)",
      "basis": [
        "Genesis 3:24 (flaming sword guarding Eden)",
        "numerous OT prophetic oracles (e.g., Isaiah 34:5–6; Ezekiel 21; Jeremiah 25)",
        "Romans 13:4 (civil authority bearing the sword)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "division, conflict, or the cost of discipleship that separates people",
      "basis": [
        "Matthew 10:34–36 (not peace but a sword; family division)",
        "Luke 12:51–53 (parallel saying)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "literal military weapon or instrument of violence/death",
      "basis": [
        "countless narrative OT and NT references (e.g., Exodus 15; 1 Samuel 17; Acts 12:2)"
      ],
      "prominence": "dominant"
    },
    {
      "meaning": "persecution, martyrdom, or the threat of death for faith",
      "basis": [
        "Romans 8:35 (sword listed among sufferings)",
        "Hebrews 11:34, 37 (saints escaping or dying by the sword)"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Context determines usage: the Word-of-God reading is the dominant metaphorical/symbolic sense in Christian teaching and NT interpretation, while judgment/warfare and literal senses remain frequent. No single meaning covers every occurrence, yet the Word-of-God identification is the most consistently taught symbolic consensus."
}
